var n=`0637-umm-ali`;var t=`world-0637`;var a=`EG`;var s=`northern-africa`;var r=8;var l=47;var d={en:`Umm Ali`,ua:`Умм Алі`};var o={en:`Umm Ali is a Egypt classic prepared with croissant, raisin, almond, desiccated coconut. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Умм Алі, страва кухні країни Єгипет зі складниками: круасан, родзинки, мигдаль, кокосова стружка. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:10,i:[[`croissant`,350,`g`],[`raisin`,100,`g`],[`almond`,80,`g`],[`desiccated-coconut`,60,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`whole-cow-milk`,700,`ml`],[`heavy-cream`,150,`ml`],[`white-granulated-sugar`,115,`g`],[`vanilla-extract`,5,`ml`]]},{en:`Bake the layered pastry and sweetened milk at 180°C until bubbling and lightly browned; serve warm.`,ua:`Запікайте листковий хліб із підсолодженим молоком при 180°C до легкого рум’янцю й бульбашок; подавайте теплим.`,t:[`roasting`],m:28,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`pistachio`,55,`g`]]}];var m={slug:n,id:t,country:`EG`,region:s,servings:8,minutes:47,title:d,text:o,steps:g};export{a as country,m as default,t as id,l as minutes,s as region,r as servings,n as slug,g as steps,o as text,d as title};